  ngOnInit(): void {
    this.subscriptions = [
      this.tsm.sessions$.subscribe(rows => this.sessionRows.set(rows)),
      this.bs.connectionStatus$.subscribe(status => this.connectionStatus.set(status)),
      this.route.params.pipe(switchMap(params => {
