   264	  getSessionColor(session: TestSession): string {
   265	    const stripes = (c1: string, c2: string) => `repeating-linear-gradient(45deg, ${c1}, ${c1} 10px, ${c2} 10px, ${c2} 20px)`;
   266	    const hsl = (h: number, s: number, l: number) => `hsl(${h}, ${s}%, ${l}%)`;
   267	    const colorful = this.displayOptions.highlightSpecies && session.booklet.species;
   268	    const h = colorful ? (
   269	      session.booklet.species.length *
   270	      session.booklet.species.charCodeAt(0) *
   271	      session.booklet.species.charCodeAt(session.booklet.species.length / 4) *
   272	      session.booklet.species.charCodeAt(session.booklet.species.length / 4) *
   273	      session.booklet.species.charCodeAt(session.booklet.species.length / 2) *
   274	      session.booklet.species.charCodeAt(3 * (session.booklet.species.length / 4)) *
   275	      session.booklet.species.charCodeAt(session.booklet.species.length - 1)
   276	    ) % 360 : 0;
   277	
   278	    switch (session.state) {
   279	      case 'paused':
   280	        return hsl(h, colorful ? 45 : 0, 90);
   281	      case 'pending':
   282	      case 'locked':
   283	        return stripes(hsl(h, colorful ? 75 : 0, 95), hsl(0, 0, 92));
   284	      case 'error':
   285	        return stripes(hsl(h, colorful ? 75 : 0, 95), hsl(0, 30, 95));
   286	      default:
   287	        return hsl(h, colorful ? 75 : 0, colorful ? 95 : 100);
   288	    }
   289	  }
